package main

import (
	"fmt"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

func newScalarNode(value string, tag string, style yaml.Style) *yaml.Node {
	return &yaml.Node{
		Kind:  yaml.ScalarNode,
		Tag:   tag,
		Value: value,
		Style: style,
	}
}

func newMapNode() *yaml.Node {
	return &yaml.Node{
		Kind: yaml.MappingNode,
		Tag:  "!!map",
	}
}

func newSeqNode() *yaml.Node {
	return &yaml.Node{
		Kind: yaml.SequenceNode,
		Tag:  "!!seq",
	}
}

func newNullNode() *yaml.Node {
	return &yaml.Node{
		Kind:  yaml.ScalarNode,
		Tag:   "!!null",
		Value: "null",
	}
}

func copyNode(n *yaml.Node) *yaml.Node {
	if n == nil {
		return nil
	}
	c := &yaml.Node{
		Kind:        n.Kind,
		Style:       n.Style,
		Tag:         n.Tag,
		Value:       n.Value,
		Anchor:      n.Anchor,
		HeadComment: n.HeadComment,
		LineComment: n.LineComment,
		FootComment: n.FootComment,
		Line:        n.Line,
		Column:      n.Column,
	}
	if n.Alias != nil {
		c.Alias = copyNode(n.Alias)
	}
	for _, ch := range n.Content {
		c.Content = append(c.Content, copyNode(ch))
	}
	return c
}

func nodeTag(n *yaml.Node) string {
	if n.Tag != "" {
		return n.Tag
	}
	switch n.Kind {
	case yaml.MappingNode:
		return "!!map"
	case yaml.SequenceNode:
		return "!!seq"
	case yaml.ScalarNode:
		return "!!str"
	}
	return ""
}

func isNull(n *yaml.Node) bool {
	if n == nil {
		return true
	}
	if n.Kind == yaml.ScalarNode && (n.Tag == "!!null" || n.Value == "null" && n.Tag == "") {
		return true
	}
	// handle explicit null tag
	if n.Tag == "!!null" {
		return true
	}
	return false
}

func isTruthy(n *yaml.Node) bool {
	if n == nil {
		return false
	}
	if isNull(n) {
		return false
	}
	if n.Kind == yaml.ScalarNode && n.Tag == "!!bool" {
		return n.Value == "true"
	}
	// empty string? In yq, "" // "hi" gave "" (empty string is truthy for //? Actually "" // "hi" gave "" (empty), so empty string is truthy (not replaced). Good.
	// 0 // "hi" gave 0, so 0 is truthy. [] // "hi" gave [], so empty array truthy. {} truthy.
	// Only null and false are falsy for //.
	return true
}

func scalarValue(n *yaml.Node) string {
	if n == nil {
		return "null"
	}
	if n.Kind != yaml.ScalarNode {
		return ""
	}
	return n.Value
}

func nodeToString(n *yaml.Node) string {
	if n == nil {
		return "null"
	}
	switch n.Kind {
	case yaml.ScalarNode:
		if n.Tag == "!!null" {
			return "null"
		}
		return n.Value
	case yaml.MappingNode, yaml.SequenceNode:
		return ""
	}
	return ""
}

func parseNumber(s string) (float64, bool, bool) { // value, isInt, ok
	if strings.Contains(s, ".") || strings.Contains(s, "e") || strings.Contains(s, "E") {
		f, err := strconv.ParseFloat(s, 64)
		if err != nil {
			return 0, false, false
		}
		return f, false, true
	}
	i, err := strconv.ParseInt(s, 10, 64)
	if err == nil {
		return float64(i), true, true
	}
	f, err := strconv.ParseFloat(s, 64)
	if err != nil {
		return 0, false, false
	}
	return f, false, true
}

func numberToNode(f float64, isInt bool) *yaml.Node {
	var s string
	var tag string
	if isInt {
		s = strconv.FormatInt(int64(f), 10)
		tag = "!!int"
	} else {
		s = strconv.FormatFloat(f, 'f', -1, 64)
		// check if it needs float tag
		tag = "!!float"
		// yq outputs 0.5 for 1/2? yes
	}
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: tag, Value: s}
}

func stringToNode(s string) *yaml.Node {
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!str", Value: s}
}

func boolToNode(b bool) *yaml.Node {
	v := "false"
	if b {
		v = "true"
	}
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!bool", Value: v}
}

func intToNode(i int) *yaml.Node {
	return &yaml.Node{Kind: yaml.ScalarNode, Tag: "!!int", Value: strconv.Itoa(i)}
}

func findMapKey(mapNode *yaml.Node, key string) (int, *yaml.Node, *yaml.Node) {
	if mapNode.Kind != yaml.MappingNode {
		return -1, nil, nil
	}
	for i := 0; i < len(mapNode.Content); i += 2 {
		k := mapNode.Content[i]
		v := mapNode.Content[i+1]
		if k.Value == key {
			return i, k, v
		}
	}
	return -1, nil, nil
}

func nodeEqual(a, b *yaml.Node) bool {
	if a == nil && b == nil {
		return true
	}
	if a == nil || b == nil {
		return false
	}
	if a.Kind != b.Kind {
		// allow int vs float? For comparison, numbers compare by value
		if a.Kind == yaml.ScalarNode && b.Kind == yaml.ScalarNode {
			// if both numbers, compare numerically
			af, _, aok := parseNumber(a.Value)
			bf, _, bok := parseNumber(b.Value)
			if aok && bok && (a.Tag == "!!int" || a.Tag == "!!float") && (b.Tag == "!!int" || b.Tag == "!!float") {
				return af == bf
			}
		}
		return false
	}
	switch a.Kind {
	case yaml.ScalarNode:
		// compare tag and value? For ==, "1" (str) vs 1 (int) should be false? In yq, "1" == 1? Likely false (different types). But numbers: 1 == 1.0 true?
		if a.Tag != b.Tag {
			// special: int vs float with same numeric value?
			if (a.Tag == "!!int" || a.Tag == "!!float") && (b.Tag == "!!int" || b.Tag == "!!float") {
				af, _, _ := parseNumber(a.Value)
				bf, _, _ := parseNumber(b.Value)
				return af == bf
			}
			return false
		}
		return a.Value == b.Value
	case yaml.SequenceNode:
		if len(a.Content) != len(b.Content) {
			return false
		}
		for i := range a.Content {
			if !nodeEqual(a.Content[i], b.Content[i]) {
				return false
			}
		}
		return true
	case yaml.MappingNode:
		if len(a.Content) != len(b.Content) {
			return false
		}
		// order matters? For ==, probably order doesn't matter? But simplify: order matters
		for i := range a.Content {
			if !nodeEqual(a.Content[i], b.Content[i]) {
				return false
			}
		}
		return true
	case yaml.AliasNode:
		return nodeEqual(a.Alias, b.Alias)
	}
	return false
}

func compareNodes(a, b *yaml.Node) (int, error) {
	// returns -1, 0, 1 for <, ==, >
	// Only for scalars? Arrays not supported for comparison (error)
	if a.Kind == yaml.SequenceNode || b.Kind == yaml.SequenceNode {
		return 0, fmt.Errorf("arrays not yet supported for comparison")
	}
	if a.Kind == yaml.MappingNode || b.Kind == yaml.MappingNode {
		return 0, fmt.Errorf("maps not yet supported for comparison")
	}
	// both scalars
	// if both numbers, compare numerically
	_, aIsNum := isNumberTag(a.Tag)
	_, bIsNum := isNumberTag(b.Tag)
	if aIsNum && bIsNum {
		af, _, _ := parseNumber(a.Value)
		bf, _, _ := parseNumber(b.Value)
		if af < bf {
			return -1, nil
		} else if af > bf {
			return 1, nil
		}
		return 0, nil
	}
	// if tags differ, compare? In yq, string vs int? Probably compare as strings? Or error?
	// For now, compare string values
	if a.Value < b.Value {
		return -1, nil
	} else if a.Value > b.Value {
		return 1, nil
	}
	return 0, nil
}

func isNumberTag(tag string) (bool, bool) {
	if tag == "!!int" || tag == "!!float" {
		return true, true
	}
	return false, false
}

func unwrapDoc(n *yaml.Node) *yaml.Node {
	if n != nil && n.Kind == yaml.DocumentNode && len(n.Content) > 0 {
		return n.Content[0]
	}
	return n
}

func wrapDoc(n *yaml.Node) *yaml.Node {
	return &yaml.Node{
		Kind:    yaml.DocumentNode,
		Content: []*yaml.Node{n},
	}
}

GOEOF
cat /workspace/nodeutil.go | head -n 20
