func sortKeysRecursive(n *yaml.Node) {
	if n.Kind == yaml.MappingNode {
		// sort key-value pairs by key string
		type kv struct {
			k, v *yaml.Node
		}
		var pairs []kv
		for i := 0; i < len(n.Content); i += 2 {
			pairs = append(pairs, kv{n.Content[i], n.Content[i+1]})
		}
		sort.Slice(pairs, func(i, j int) bool {
			return pairs[i].k.Value < pairs[j].k.Value
		})
		n.Content = nil
		for _, p := range pairs {
			n.Content = append(n.Content, p.k, p.v)
			sortKeysRecursive(p.v)
		}
	} else if n.Kind == yaml.SequenceNode {
		for _, c := range n.Content {
			sortKeysRecursive(c)
		}
	} else if n.Kind == yaml.DocumentNode {
		for _, c := range n.Content {
			sortKeysRecursive(c)
		}
	}
}

