				inStr = 0
			}
			continue
		}
		if c == '"' || c == '\'' {
			inStr = c
			cur.WriteByte(c)
			continue
		}
		if c == '{' || c == '[' || c == '(' {
			depth++
			cur.WriteByte(c)
			continue
		}
		if c == '}' || c == ']' || c == ')' {
