func flattenProps(n *yaml.Node, prefix string, lines *[]string, opts *Options, sep string) {
	switch n.Kind {
	case yaml.MappingNode:
		for i := 0; i < len(n.Content); i += 2 {
			k := n.Content[i].Value
			v := n.Content[i+1]
			newPrefix := k
			if prefix != "" {
				newPrefix = prefix + "." + k
			}
			flattenProps(v, newPrefix, lines, opts, sep)
		}
	case yaml.SequenceNode:
		for i, c := range n.Content {
			var newPrefix string
			if opts.PropsArrayBrackets {
				newPrefix = fmt.Sprintf("%s[%d]", prefix, i)
			} else {
				if prefix == "" {
					newPrefix = strconv.Itoa(i)
				} else {
					newPrefix = prefix + "." + strconv.Itoa(i)
				}
			}
			flattenProps(c, newPrefix, lines, opts, sep)
		}
	case yaml.ScalarNode:
		val := n.Value
		if n.Tag == "!!null" {
			val = "null"
		}
		*lines = append(*lines, prefix+sep+val)
	case yaml.AliasNode:
		if n.Alias != nil {
			flattenProps(n.Alias, prefix, lines, opts, sep)
		}
	}
}

