		// Check for explicit subcommand in remaining args (fs.Args() may be incomplete due to error? Use raw args to detect subcommand before error? For `eval --unknown`, subcommand is eval, show eval usage. Good – detect subcommand from raw args (first non-flag that is subcommand).
		sub := detectSubcommandRaw(args)
		var usage string
		if sub == "eval" || sub == "e" {
